mapper.sql:
select o.id as order_id, o.school_id, o.school_name, o.supplier_id, o.supplier_name, o.dept_id, date_format(coalesce(o.pay_time, o.create_time), '%Y-%m') as settlement_cycle, greatest(coalesce(o.pay_amount, 0) - coalesce(o.refund_amount, 0), 0) as net_amount, case when sf.order_id is null then 0 else 1 end as settled_flag, sf.last_settlement_time, o.create_time as order_create_time from xfpt_order_info o inner join xfpt_school_supplier_rel sr on sr.school_id = o.school_id and sr.supplier_id = o.supplier_id and sr.cooperate_status = '1' and sr.del_flag = '0' left join ( select order_id, supplier_id, max(trade_time) as last_settlement_time from xfpt_finance_flow where del_flag = '0' and business_type = '4' and flow_direction = '1' and payee_type = '2' group by order_id, supplier_id ) sf on sf.order_id = o.id and sf.supplier_id = o.supplier_id where o.del_flag = '0' and o.supplier_id is not null and o.pay_status in ('1', '2', '3') and greatest(coalesce(o.pay_amount, 0) - coalesce(o.refund_amount, 0), 0) > 0
and o.dept_id = #{deptId}
and o.school_id = #{params.schoolId}

