) s
where 1 = 1
  and s.id = #{id}
  and s.unit_name like concat('%', #{unitName}, '%')
  and s.supplier_name like concat('%', #{supplierName}, '%')
  and s.project_name like concat('%', #{projectName}, '%')
  and s.settlement_cycle = #{settlementCycle}
  and s.status = #{status}
order by s.settlement_cycle desc, s.supplier_id desc

select *
from (

) s
where s.id = #{id}
limit 1
